#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# gh must run inside the repository, whatever folder the wizard was started from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
# Without ENV_FILE the library would write a .env into the repository; use the project's usual settings file instead.
if [[ "$ENV_FILE" == ".env" ]]; then ENV_FILE="$HOME/leekcf-env/staging.env"; fi

TOTAL_STAGES=6

# Starts the workflow's test run and waits for it. $1 is the workflow file; the dispatch itself is done by the caller.
latest_run_id() { gh run list --workflow "$1" --limit 1 --json databaseId -q '.[0].databaseId // empty' 2>/dev/null || true; }
wait_for_run() {
  local workflow="$1" before="$2" id="" tries=0
  until [[ -n "$id" && "$id" != "$before" ]] || (( tries >= 15 )); do sleep 3; id=$(latest_run_id "$workflow"); tries=$((tries + 1)); done
  if [[ -z "$id" || "$id" == "$before" ]]; then
    warn "$workflow: GitHub did not show the run. Look in the repository's Actions tab."
    return
  fi
  say "Waiting for $workflow (run $id)..."
  if gh run watch "$id" --exit-status >/dev/null 2>&1; then
    say "$workflow: it worked."
  else
    warn "$workflow: it failed. Read why with:  gh run view $id --log-failed"
    FAILED_RUNS+=("$workflow")
  fi
}
FAILED_RUNS=()

banner "Deploys and backups on GitHub, so nothing is left on this computer"
note "Run this after scripts/setup-github-automation.sh. Settings go to $ENV_FILE and, with your OK, to GitHub."
printf '\n'

# ── 1. The Cloudflare deploy token ────────────────────────────────────────
stage "Cloudflare: a token that may deploy the API"
say "GitHub will deploy the API whenever its code changes, so nobody has to run 'wrangler deploy' on a computer."
say "It needs a token that may edit Workers. It is a different token from the usage-statistics one, so each key can do one job."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Click 'Create Token'."
step "Next to 'Edit Cloudflare Workers', click 'Use template'."
step "Token name: leekcf-hinter-deploy"
step "Account Resources: 'Include', then your account. If it asks for Zone Resources, 'All zones' is fine: this project uses none."
step "Click 'Continue to summary', then 'Create Token'."
step "Copy the token. Cloudflare shows it only once."
note "Cloudflare changes its dashboard now and then. If a label differs, the permission you need is Account → Workers Scripts → Edit."
ask_secret CLOUDFLARE_DEPLOY_TOKEN "Paste the token (nothing shows while you paste):"
write_env CLOUDFLARE_DEPLOY_TOKEN "$CLOUDFLARE_DEPLOY_TOKEN"
# The header goes in through stdin, so the token is never on a command line where other programs could read it.
cf_header="Authorization: Bearer $CLOUDFLARE_DEPLOY_TOKEN"
cf_answer=$(curl -fsS -H @- https://api.cloudflare.com/client/v4/user/tokens/verify <<<"$cf_header" 2>/dev/null || true)
if grep -q '"status":"active"' <<<"$cf_answer"; then
  say "Cloudflare says the token is valid."
else
  warn "Cloudflare did not confirm the token. Check that you copied all of it."
  note "Press Ctrl-C now to start again (this wizard remembers your answers), or Enter to carry on."
  pause
fi

# ── 2. The private backup repository ──────────────────────────────────────
stage "GitHub: a private repository for the backups"
owner=$(gh repo view --json owner -q .owner.login 2>/dev/null || true)
if [[ -z "$owner" ]]; then warn "gh does not know this repository. Run 'gh auth login' first, then start this wizard again."; exit 1; fi
BACKUP_REPO="$owner/LeekCF-Hinter-backups"
say "Every day GitHub saves the whole database (statements, editorials, hints, usage numbers) into $BACKUP_REPO."
warn "It must be PRIVATE: the statements and editorials are Codeforces' text and must not be published."
if gh repo view "$BACKUP_REPO" >/dev/null 2>&1; then
  if [[ "$(gh repo view "$BACKUP_REPO" --json isPrivate -q .isPrivate)" != "true" ]]; then
    warn "$BACKUP_REPO exists but is PUBLIC. Make it private in its Settings → Danger Zone, then start this wizard again."
    exit 1
  fi
  say "$BACKUP_REPO exists already and is private. It will be used."
else
  say "It does not exist yet."
  if ! confirm "Create the private repository $BACKUP_REPO now? (type y)"; then
    warn "Nothing was created. Start this wizard again when you are ready."
    exit 1
  fi
  gh repo create "$BACKUP_REPO" --private --description "Private daily database backups of LeekCF-Hinter" >/dev/null
  say "Created $BACKUP_REPO (private)."
fi

# ── 3. The key that writes only there ─────────────────────────────────────
stage "GitHub: a key that can write to that one repository"
say "The backup job needs to save files into $BACKUP_REPO. A deploy key can do that and nothing else: it opens no other repository."
key_title="leekcf-hinter backup (write)"
keydir=$(mktemp -d)
if ! ssh-keygen -q -t ed25519 -N "" -C "leekcf-hinter-backup" -f "$keydir/key"; then
  rm -rf "$keydir"; warn "Could not make a key (is ssh-keygen installed?)."; exit 1
fi
# A key with the same name from an earlier run is replaced, so running this twice leaves one key.
for old_id in $(gh repo deploy-key list --repo "$BACKUP_REPO" --json id,title --jq ".[] | select(.title==\"$key_title\") | .id" 2>/dev/null); do
  gh repo deploy-key delete "$old_id" --repo "$BACKUP_REPO" >/dev/null 2>&1 || true
done
if gh repo deploy-key add "$keydir/key.pub" --repo "$BACKUP_REPO" --title "$key_title" --allow-write >/dev/null; then
  say "Added the public half to $BACKUP_REPO as a deploy key with write access."
  set_secret BACKUP_DEPLOY_KEY "$(cat "$keydir/key")"
else
  warn "GitHub refused the deploy key. Does your gh login have the 'repo' permission?"
  rm -rf "$keydir"; exit 1
fi
rm -rf "$keydir"
note "The private half now exists only as an encrypted GitHub secret. The copy on this computer was deleted."

# ── 4. Store the rest on GitHub ───────────────────────────────────────────
stage "GitHub: store the deploy token and the backup setting"
target=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo "this repository")
say "Target: $target."
say "Secret: the Cloudflare deploy token (GitHub keeps it encrypted; only its workflows can read it)."
say "Setting: BACKUP_REPO=$BACKUP_REPO  (not secret)"
if confirm "Store them in $target?"; then
  set_secret CLOUDFLARE_DEPLOY_TOKEN "$CLOUDFLARE_DEPLOY_TOKEN"
  set_var BACKUP_REPO "$BACKUP_REPO"
else
  SKIPPED+=("The deploy token and BACKUP_REPO: run this wizard again, or see docs/automation.md")
fi

# ── 5. Test runs ──────────────────────────────────────────────────────────
stage "GitHub: try the backup and the deploy once"
say "1) The backup exports the database, checks it can be read back, and saves it in $BACKUP_REPO."
say "2) The deploy runs the API's tests, deploys the API to Cloudflare, and checks it answers. Same code as now, so users notice nothing."
note "Each takes a minute or two. This wizard waits and tells you whether it worked."
if confirm "Start both test runs now?"; then
  backup_before=$(latest_run_id backup.yml)
  deploy_before=$(latest_run_id deploy-worker.yml)
  gh workflow run backup.yml >/dev/null 2>&1 || { warn "Could not start backup.yml. Are the workflows pushed to main?"; SKIPPED+=("gh workflow run backup.yml"); }
  gh workflow run deploy-worker.yml >/dev/null 2>&1 || { warn "Could not start deploy-worker.yml. Are the workflows pushed to main?"; SKIPPED+=("gh workflow run deploy-worker.yml"); }
  wait_for_run backup.yml "$backup_before"
  wait_for_run deploy-worker.yml "$deploy_before"
else
  SKIPPED+=("Test runs: gh workflow run backup.yml ; gh workflow run deploy-worker.yml")
fi
pause "Press Enter to continue."

# ── 6. Switch them on ─────────────────────────────────────────────────────
stage "GitHub: switch the daily backup and the automatic deploy on"
say "Backup: every day at 04:30 UTC (07:30 in Jordan), the newest 30 are kept."
say "Deploy: every time the API's code on main changes."
if (( ${#FAILED_RUNS[@]} )); then
  warn "A test run failed (${FAILED_RUNS[*]}). Say n, fix it, and switch them on later."
fi
note "Later: gh variable set BACKUP_ENABLED --body true ; gh variable set DEPLOY_ENABLED --body true"
if confirm "Switch both on now?"; then
  set_var BACKUP_ENABLED true
  set_var DEPLOY_ENABLED true
else
  SKIPPED+=("Switch them on: gh variable set BACKUP_ENABLED --body true ; gh variable set DEPLOY_ENABLED --body true")
fi

finish
}

run_wizard "$@"; exit
